// Method: TreeItem::set_custom_draw
static JSValue js_TreeItem_set_custom_draw(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_custom_draw: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_custom_draw: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_custom_draw: invalid or freed object");
    }

    TreeItem* typed_obj = Object::cast_to<TreeItem>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_custom_draw: object is not a TreeItem");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 4) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_custom_draw: expected at least 3 arguments, got %d", argc - 1);
    }

    // Convert arguments
    int64_t arg_column; JS_ToInt64(ctx, &arg_column, argv[1]);
    Object* arg_object = nullptr;
    if (JS_IsNumber(argv[2])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_object; JS_ToInt64(ctx, &h_object, argv[2]);
        Object* obj_object = qjs_ctx->get_object_registry()->get_object(h_object);
        arg_object = reinterpret_cast<Object*>(obj_object);
    } else {
        // Object with __handle property
        JSValue jh_object = JS_GetPropertyStr(ctx, argv[2], "__handle");
        if (!JS_IsUndefined(jh_object)) {
            int64_t h_object; JS_ToInt64(ctx, &h_object, jh_object);
            Object* obj_object = qjs_ctx->get_object_registry()->get_object(h_object);
            arg_object = reinterpret_cast<Object*>(obj_object);
        }
        JS_FreeValue(ctx, jh_object);
    }
    const char* cstr_callback = JS_ToCString(ctx, argv[3]); StringName arg_callback = cstr_callback ? cstr_callback : ""; JS_FreeCString(ctx, cstr_callback);

    typed_obj->set_custom_draw(arg_column, arg_object, arg_callback);
    return JS_UNDEFINED;
}

