// Method: TreeItem::set_button
static JSValue js_TreeItem_set_button(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_button: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_button: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_button: invalid or freed object");
    }

    TreeItem* typed_obj = Object::cast_to<TreeItem>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_button: object is not a TreeItem");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 4) {
        return JS_ThrowTypeError(ctx, "TreeItem.set_button: expected at least 3 arguments, got %d", argc - 1);
    }

    // Convert arguments
    int64_t arg_column; JS_ToInt64(ctx, &arg_column, argv[1]);
    int64_t arg_button_index; JS_ToInt64(ctx, &arg_button_index, argv[2]);
    Ref<Texture2D> arg_button;
    if (JS_IsNumber(argv[3])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_button; JS_ToInt64(ctx, &h_button, argv[3]);
        Object* obj_button = qjs_ctx->get_object_registry()->get_object(h_button);
        arg_button = Ref<Texture2D>(Object::cast_to<Texture2D>(obj_button));
    } else {
        // Object with __handle property
        JSValue jh_button = JS_GetPropertyStr(ctx, argv[3], "__handle");
        if (!JS_IsUndefined(jh_button)) {
            int64_t h_button; JS_ToInt64(ctx, &h_button, jh_button);
            Object* obj_button = qjs_ctx->get_object_registry()->get_object(h_button);
            arg_button = Ref<Texture2D>(Object::cast_to<Texture2D>(obj_button));
        }
        JS_FreeValue(ctx, jh_button);
    }

    typed_obj->set_button(arg_column, arg_button_index, arg_button);
    return JS_UNDEFINED;
}

